SELECT p.supplier_id, CASE WHEN p.stock_qty >= 413 THEN 'high' WHEN p.stock_qty >= 194 THEN 'mid' ELSE 'low' END AS stock_qty_bucket, MAX(i.quantity) AS max_quantity, AVG(i.quantity) AS avg_quantity FROM inventory i LEFT OUTER JOIN products p ON i.product_id = p.id JOIN stores s ON i.store_id = s.id GROUP BY p.supplier_id, CASE WHEN p.stock_qty >= 413 THEN 'high' WHEN p.stock_qty >= 194 THEN 'mid' ELSE 'low' END HAVING max_quantity >= 90;
